// MODULES //

var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var abs = require( '@stdlib/math/base/special/abs' );
var dscal = require( '@stdlib/blas/base/dscal/lib/ndarray.js' );
var dswap = require( '@stdlib/blas/base/dswap/lib/ndarray.js' );


// FUNCTIONS //

/**
* Returns the first logical absolute maximum without allocation.
* @private
* @param {PositiveInteger} n - count
* @param {Float64Array} x - data
* @param {integer} s - stride
* @param {integer} o - offset
* @returns {integer} zero-based ordinal
*/
function firstabsmax(n, x, s, o) {
	var index;
	var value;
	var best;
	var i;
	best = abs(x[o]);
	index = 0;
	for (i = 1; (i < n); i += 1) {
		value = abs(x[(o + (i * s))]);
		if ((value > best)) {
			best = value;
			index = i;
		}
	}
	return index;
}
/**
* Applies fixed-alpha-minus-one reference GER in original Y-outer order.
* @private
* @param {PositiveInteger} M - update rows
* @param {PositiveInteger} N - update columns
* @param {Float64Array} AB - shared band storage
* @param {integer} r - original row stride
* @param {integer} d - original diagonal stride
* @param {integer} ox - multiplier start
* @param {integer} oy - original Y start
* @param {integer} oa - update start
* @returns {void}
*/
function ger(M, N, AB, r, d, ox, oy, oa) {
	var temp;
	var ia;
	var iy;
	var i;
	var j;
	for (j = 0; (j < N); j += 1) {
		iy = (oy + (j * d));

		// Preserve the reference Y-zero skip; there is no X-zero skip.
		if ((AB[iy] !== 0)) {
			temp = (-1 * AB[iy]);
			for (i = 0; (i < M); i += 1) {
				ia = ((oa + (i * r)) + (j * d));
				AB[ia] = (AB[ia] + (AB[(ox + (i * r))] * temp));
			}
		}
	}
}


// MAIN //

/**
* Translates unchanged Reference-LAPACK DGBTF2 elimination order.
*
* The private update follows DGER (Dongarra, Du Croz, Hammarling, Hanson).
* No reciprocal safe-minimum repair or allocation is introduced.
*
* @private
* @param {PositiveInteger} M - original rows
* @param {PositiveInteger} N - original columns
* @param {NonNegativeInteger} KL - lower bandwidth
* @param {NonNegativeInteger} KU - upper bandwidth
* @param {Float64Array} AB - full compact band view
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - offset
* @param {Int32Array} PIV - positive one-based step swap output
* @param {integer} sp - pivot stride
* @param {integer} op - pivot offset
* @returns {NonNegativeInteger} first computed zero pivot or zero
*/
function dgbtf2(M, N, KL, KU, AB, r, c, o, PIV, sp, op) { // eslint-disable-line max-params
	var column;
	var count;
	var pivot;
	var start;
	var info;
	var jp;
	var ju;
	var km;
	var kv;
	var d;
	var i;
	var j;
	var k;
	kv = (KL + KU);
	k = min(M, N);
	ju = 1;
	info = 0;

	// Original fill capacity is not original matrix input.
	for (j = (KU + 1); (j < min(kv, N)); j += 1) {
		for (i = (kv - j); (i < KL); i += 1) {
			AB[((o + (i * r)) + (j * c))] = 0;
		}
	}
	for (j = 0; (j < k); j += 1) {
		if (((j + kv) < N)) {
			for (i = 0; (i < KL); i += 1) {
				AB[((o + (i * r)) + ((j + kv) * c))] = 0;
			}
		}
		km = min(KL, ((M - j) - 1));
		column = (o + (j * c));
		start = (column + (kv * r));
		jp = firstabsmax((km + 1), AB, r, start);
		PIV[(op + (j * sp))] = ((j + jp) + 1);
		pivot = AB[(start + (jp * r))];
		if ((pivot !== 0)) {
			ju = max(ju, min((((j + KU) + jp) + 1), N));
			if ((jp !== 0)) {
				count = (ju - j);
				d = (count === 1) ? 1 : (c - r);
				dswap(count, AB, d, (start + (jp * r)), AB, d, start);
			}
			if ((km > 0)) {
				// Intentionally retain finite-input reciprocal overflow observations.
				dscal(km, (1 / AB[start]), AB, r, (start + r));
				count = ((ju - j) - 1);
				if ((count > 0)) {
					d = (c - r);
					ger(km, count, AB, r, d, (start + r), ((column + c) + ((kv - 1) * r)), (start + c));
				}
			}
		} else if ((info === 0)) {
			info = (j + 1);
		}
	}
	return info;
}


// EXPORTS //

module.exports = dgbtf2;
